export declare const MIGRATE_SCHEMA_V2_TO_V3_SQL = "\nALTER TABLE meetings ADD COLUMN recording_started_at_ms INTEGER\n  CHECK (\n    recording_started_at_ms IS NULL OR\n    (origin = 'recording' AND recording_started_at_ms >= created_at_ms)\n  );\nALTER TABLE meetings ADD COLUMN recording_ended_at_ms INTEGER\n  CHECK (\n    recording_ended_at_ms IS NULL OR\n    (origin = 'recording' AND recording_started_at_ms IS NOT NULL AND\n     recording_ended_at_ms >= recording_started_at_ms)\n  );\nPRAGMA user_version = 3;\n";
export declare const MIGRATE_SCHEMA_V3_TO_V4_SQL = "\nALTER TABLE meetings ADD COLUMN run_identity TEXT CHECK (length(run_identity) <= 1024);\nALTER TABLE meetings ADD COLUMN transcript_identity TEXT CHECK (length(transcript_identity) <= 1024);\nPRAGMA user_version = 4;\n";
export declare const SCHEMA_V4_SQL: string;
export declare const MIGRATE_SCHEMA_V4_TO_V5_SQL = "\n\nCREATE TABLE okf_ingestion (\n  meeting_id          TEXT NOT NULL\n                      REFERENCES meetings(meeting_id) ON DELETE CASCADE,\n  transcript_version  INTEGER NOT NULL CHECK (transcript_version >= 0),\n  directory           TEXT NOT NULL\n                      CHECK (length(directory) BETWEEN 1 AND 1024),\n  state               TEXT NOT NULL\n                      CHECK (state IN ('running', 'succeeded', 'failed')),\n  attempt             INTEGER NOT NULL CHECK (attempt >= 1),\n  started_at_ms       INTEGER NOT NULL CHECK (started_at_ms > 0),\n  finished_at_ms      INTEGER\n                      CHECK (finished_at_ms IS NULL OR finished_at_ms > 0),\n  error_code          TEXT\n                      CHECK (error_code IS NULL OR length(error_code) BETWEEN 1 AND 100),\n  error_message       TEXT\n                      CHECK (error_message IS NULL OR length(error_message) BETWEEN 1 AND 500),\n  PRIMARY KEY (meeting_id, transcript_version, directory),\n  CHECK (state <> 'failed' OR error_code IS NOT NULL),\n  CHECK (state = 'running' OR finished_at_ms IS NOT NULL),\n  CHECK (\n    state <> 'running' OR\n    (finished_at_ms IS NULL AND error_code IS NULL AND error_message IS NULL)\n  )\n) STRICT;\n\nCREATE INDEX idx_okf_ingestion_latest\nON okf_ingestion(meeting_id, started_at_ms DESC, attempt DESC);\n\nPRAGMA user_version = 5;\n";
export declare const SCHEMA_V5_SQL: string;
export declare const MIGRATE_SCHEMA_V5_TO_V6_SQL = "\n\nCREATE TABLE meeting_speaker_names (\n  meeting_id  TEXT NOT NULL\n              REFERENCES meetings(meeting_id) ON DELETE CASCADE,\n  label       TEXT NOT NULL CHECK (length(label) BETWEEN 1 AND 120),\n  name        TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 60),\n  PRIMARY KEY (meeting_id, label)\n) STRICT;\n\nPRAGMA user_version = 6;\n";
